        // Assume a field 'pattern' exists in the enclosing class
        String pattern = this.pattern;
        if (pattern == null) {
            // Default pattern if none is set
            pattern = "%d [%t] %-5p %c - %m%n";
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < pattern.length(); i++) {
            char c = pattern.charAt(i);
            if (c == '%' && i + 1 < pattern.length()) {
                char next = pattern.charAt(i + 1);
                switch (next) {
                    case 'm':
                        sb.append(String.valueOf(event.getMessage()));
                        i++;
                        break;
                    case 'p':
                        sb.append(String.valueOf(event.getLevel()));
                        i++;
                        break;
                    case 't':
                        sb.append(String.valueOf(event.getThreadName()));
                        i++;
                        break;
