        if (cache == null) {
            cache = data;
        } else {
            // Attempt to merge the new data with the existing cached value.
            // The METRICS type is expected to provide a merge method; if it does not,
            // we fall back to replacing the cached value.
            try {
                cache.merge(data);
            } catch (NoSuchMethodError | UnsupportedOperationException e) {
                // Fallback: replace the cached value with the new data
                cache = data;
