static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        throw new IllegalArgumentException("dayStep must be positive");
    }
    // Extract year, month, day from YYYYMMDD format
    int year = (int)(timeBucket / 10000);
    int month = (int)((timeBucket / 100) % 100);
    int day = (int)(timeBucket % 100);

    // Basic validation of date components
    if(month < 1 || month > 12){
        throw new IllegalArgumentException("Invalid month in timeBucket: " + month);
    }
    if(day < 1 || day > 31){
        throw new IllegalArgumentException("Invalid day in timeBucket: " + day);
    }

    // Compute the compressed day bucket
    int bucketDay = 1 + ((day - 1) / dayStep) * dayStep;

    // Ensure bucketDay does not exceed the maximum days in the month
    // (simple check for 30/31 days, ignoring leap years for February)
    int maxDayInMonth;
    switch(month){
        case 2:
            // Simplified: treat February as 29 days for leap year safety
            maxDayInMonth = 29;
            break;
        case 4: case 6: case 9: case 11:
            maxDayInMonth = 30;
            break;
        default:
            maxDayInMonth = 31;
    }
    if(bucketDay > maxDayInMonth){
        // If the computed bucket day exceeds the month length, clamp to last day
        bucketDay = maxDayInMonth;
    }

    return year * 10000L + month * 100L + bucketDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("String must not be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException(
                "index: " + index + ", len: " + len + ", str.length(): " + str.length());
    }
    int end = index + len;
    int i = index;
    int total = 0;
    while (i < end) {
        int cp = str.codePointAt(i);
        int cpLen = Character.charCount(cp);
        if (i + cpLen > end) {
            throw new IndexOutOfBoundsException(
                    "Surrogate pair at index " + i + " extends beyond the specified length");
        }
        if (cp <= 0x7F) {
            total += 1;
        } else if (cp <= 0x7FF) {
            total += 2;
        } else if (cp <= 0xFFFF) {
            total += 3;
        } else {
            total += 4;
        }
        i += cpLen;
    }
    return total;
}

