public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    if (byteArrayValue != null) {
        if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
            throw new IllegalArgumentException("byteOffset out of bounds");
        }
        if (byteOffset + byteLength > byteArrayValue.length) {
            throw new IllegalArgumentException("byteOffset + byteLength exceeds array length");
        }
    }
    int newLength = this.length + byteLength;
    if (newLength > data.length) {
        int newCapacity = Math.max(newLength, data.length * 2);
        if (newCapacity == 0) {
            newCapacity = newLength;
        }
        byte[] newData = new byte[newCapacity];
        System.arraycopy(data, 0, newData, 0, this.length);
        data = newData;
    }
    if (byteLength > 0) {
        if (byteArrayValue == null) {
            for (int i = 0; i < byteLength; i++) {
                data[this.length + i] = 0;
            }
        } else {
            System.arraycopy(byteArrayValue, byteOffset, data, this.length, byteLength);
        }
    }
    this.length = newLength;
    return this;
}

