public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new NullPointerException("str");
    }
    if (lb == null) {
        throw new NullPointerException("lb");
    }
    final int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c >= 0xD800 && c <= 0xDBFF) { // high surrogate
            if (i + 1 >= len) {
                throw new IllegalArgumentException("High surrogate at end of string");
            }
            char low = str.charAt(i + 1);
            if (low < 0xDC00 || low > 0xDFFF) {
                throw new IllegalArgumentException("High surrogate not followed by low surrogate");
            }
            int codepoint = ((c - 0xD800) << 10) + (low - 0xDC00) + 0x10000;
            // 4-byte UTF-8
            lb.write((byte) (0xF0 | (codepoint >> 18)));
            lb.write((byte) (0x80 | ((codepoint >> 12) & 0x3F)));
            lb.write((byte) (0x80 | ((codepoint >> 6) & 0x3F)));
            lb.write((byte) (0x80 | (codepoint & 0x3F)));
            i++; // skip low surrogate
        } else if (c >= 0xDC00 && c <= 0xDFFF) { // low surrogate without preceding high
            throw new IllegalArgumentException("Low surrogate without preceding high surrogate");
        } else {
            if (c <= 0x7F) { // 1-byte
                lb.write((byte) c);
            } else if (c <= 0x7FF) { // 2-byte
                lb.write((byte) (0xC0 | (c >> 6)));
                lb.write((byte) (0x80 | (c & 0x3F)));
            } else { // 3-byte
                lb.write((byte) (0xE0 | (c >> 12)));
                lb.write((byte) (0x80 | ((c >> 6) & 0x3F)));
                lb.write((byte) (0x80 | (c & 0x3F)));
            }
        }
    }
    return lb;
}

public void removeFromTreeEdgeList() {
    try {
        // Remove from source node's tree edge list
        if (source != null) {
            if (treeEdgePrev != null) {
                treeEdgePrev.treeEdgeNext = treeEdgeNext;
            } else {
                source.treeEdgeHead = treeEdgeNext;
            }
            if (treeEdgeNext != null) {
                treeEdgeNext.treeEdgePrev = treeEdgePrev;
            } else {
                source.treeEdgeTail = treeEdgePrev;
            }
        }

        // Remove from target node's tree edge list
        if (target != null) {
            if (treeEdgePrevOpposite != null) {
                treeEdgePrevOpposite.treeEdgeNextOpposite = treeEdgeNextOpposite;
            } else {
                target.treeEdgeHead = treeEdgeNextOpposite;
            }
            if (treeEdgeNextOpposite != null) {
                treeEdgeNextOpposite.treeEdgePrevOpposite = treeEdgePrevOpposite;
            } else {
                target.treeEdgeTail = treeEdgePrevOpposite;
            }
        }

        // Nullify this edge's pointers
        treeEdgePrev = null;
        treeEdgeNext = null;
        treeEdgePrevOpposite = null;
        treeEdgeNextOpposite = null;
    } catch (Exception e) {
        throw new IllegalStateException("Failed to remove edge from tree edge list", e);
    }
}

public static String findAndSubst(String key, Properties props) {
    if (key == null) {
        throw new IllegalArgumentException("key must not be null");
    }
    if (props == null) {
        throw new IllegalArgumentException("props must not be null");
    }
    String value = props.getProperty(key);
    if (value == null) {
        throw new IllegalArgumentException("Property for key '" + key + "' not found");
    }
    java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\$\\{([^}]+)}");
    String result = value;
    int maxDepth = 10;
    for (int depth = 0; depth < maxDepth; depth++) {
        java.util.regex.Matcher matcher = pattern.matcher(result);
        boolean found = false;
        StringBuffer sb = new StringBuffer();
        while (matcher.find()) {
            found = true;
            String varKey = matcher.group(1);
            String varValue = props.getProperty(varKey);
            if (varValue == null) {
                varValue = matcher.group(0);
            }
            matcher.appendReplacement(sb, java.util.regex.Matcher.quoteReplacement(varValue));
        }
        matcher.appendTail(sb);
        result = sb.toString();
        if (!found) {
            break;
        }
    }
    return result;
}

