private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    // If both are null, consider it a match
    if (str == null && suffix == null) {
        return true;
    }
    // If one is null and the other is not, no match
    if (str == null || suffix == null) {
        return false;
    }
    int suffixLen = suffix.length();
    int strLen = str.length();
    // If suffix is longer than the string, it cannot match
    if (suffixLen > strLen) {
        return false;
    }
    // Use regionMatches to handle case-insensitive comparison if requested
    return str.regionMatches(ignoreCase, strLen - suffixLen, suffix, 0, suffixLen);
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new IllegalArgumentException("URI cannot be null");
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return new ArrayList<>();
    }
    // Remove leading slash if present (absolute path)
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    // Split on '/' keeping empty segments (e.g., trailing slash)
    String[] parts = path.split("/", -1);
    List<PathSegmentImpl> segments = new ArrayList<>(parts.length);
    for (String part : parts) {
        String segment = part;
        if (decode) {
            try {
                segment = java.net.URLDecoder.decode(part, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (IllegalArgumentException e) {
                throw new IllegalArgumentException("Invalid percent-encoding in segment: " + part, e);
            }
        }
        segments.add(new PathSegmentImpl(segment));
    }
    return segments;
}

