private void enlarge(final int size) {
    if (size <= 0) {
        throw new IllegalArgumentException("size must be positive");
    }
    // current capacity of the underlying byte array
    int currentCapacity = (data == null) ? 0 : data.length;
    // number of bytes currently stored (assumed field name 'size')
    int used = this.size;
    // required capacity to accommodate additional 'size' bytes
    int required = used + size;
    if (required <= currentCapacity) {
        return; // already enough space
    }
    // grow strategy: double the capacity or meet the required size, whichever is larger
    int newCapacity = Math.max(currentCapacity * 2, required);
    if (newCapacity < 0) { // overflow check
        throw new OutOfMemoryError("Required capacity too large");
    }
    byte[] newData = new byte[newCapacity];
    if (data != null) {
        System.arraycopy(data, 0, newData, 0, used);
    }
    data = newData;
}

