private void putAbstractTypes(final int start, final int end) {
    if (currentFrame == null) {
        throw new IllegalStateException("currentFrame is null");
    }
    if (stackMapTableEntries == null) {
        throw new IllegalStateException("stackMapTableEntries is null");
    }
    if (start < 0 || end > currentFrame.length || start > end) {
        throw new IllegalArgumentException("Invalid start or end indices");
    }
    try {
        for (int i = start; i < end; i++) {
            AbstractType type = currentFrame[i];
            if (type == null) {
                throw new IllegalStateException("AbstractType at index " + i + " is null");
            }
            int tag = type.getTag();
            stackMapTableEntries.write(tag);
            if (tag == 0x07) { // OBJECT
                int cpoolIndex = type.getCpoolIndex();
                stackMapTableEntries.write((cpoolIndex >> 8) & 0xFF);
                stackMapTableEntries.write(cpoolIndex & 0xFF);
            } else if (tag == 0x08) { // UNINITIALIZED
                int offset = type.getOffset();
                stackMapTableEntries.write((offset >> 8) & 0xFF);
                stackMapTableEntries.write(offset & 0xFF);
            }
        }
    } catch (IOException e) {
        throw new RuntimeException("Failed to write abstract types", e);
    }
}

public void readFrom(final InputStream in) throws IOException {
    if (in == null) {
        throw new NullPointerException("InputStream cannot be null");
    }
    // Read all bytes from the input stream into a temporary buffer
    java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
    byte[] chunk = new byte[8192];
    int read;
    while ((read = in.read(chunk)) != -1) {
        baos.write(chunk, 0, read);
    }
    // Store the read bytes into the ClassFileBuffer's internal buffer
    this.buffer = baos.toByteArray();
    // Reset the read pointer to the start of the buffer
    this.readPointer = 0;
}

