            continue;
        }
        if (lowerStr.contains(search.toLowerCase())) {
            return true;
        }
    }
    return false;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("desiredCapacity must be positive");
    }
    // Handle small capacities directly
    if (desiredCapacity <= 2) {
        return 2;
    }
    // Ensure candidate is odd
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++;
    }
    // Determine maximum allowed if within 11% range
    int maxAllowed = Integer.MAX_VALUE;
    if (desiredCapacity >= 1000) {
        long temp = (long) desiredCapacity * 111L / 100L; // floor of 1.11 * desiredCapacity
        if (temp > Integer.MAX_VALUE) {
            maxAllowed = Integer.MAX_VALUE;
        } else {
            maxAllowed = (int) temp;
        }
    }
    // Search for prime within allowed range first
    for (int n = candidate; n <= maxAllowed; n += 2) {
        if (isPrime(n)) {
            return n;
        }
    }
    // If not found within range, continue searching beyond maxAllowed
    for (int n = maxAllowed + 2; n > 0; n += 2) { // n > 0 to avoid overflow
        if (isPrime(n)) {
            return n;
        }
    }
    // Should never reach here
    throw new RuntimeException("Unable to find a prime number");
}

