protected int removeUnusedNodes() {
    int removedCount = 0;
    try {
        // If this node has no children, nothing to remove
        if (this.children == null) {
            return 0;
        }
        // Use an iterator to safely remove elements while iterating
        java.util.Iterator<Category> it = this.children.iterator();
        while (it.hasNext()) {
            Category child = it.next();
            if (child == null) {
                continue;
            }
            // If the child is inactive, remove it and its entire subtree
            if (!child.isActive()) {
                // Count the child itself plus all nodes in its subtree
                removedCount += 1 + child.removeUnusedNodes();
                it.remove();
            } else {
                // Recursively remove unused nodes from the active child's subtree
                removedCount += child.removeUnusedNodes();
            }
        }
    } catch (Exception e) {
        // Wrap any unexpected exception in an IllegalStateException
        throw new IllegalStateException("Error while removing unused nodes", e);
    }
    return removedCount;
}

