private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate must not be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("Start and stop nodes must not be null");
    }
    if (dir != 1 && dir != -1) {
        throw new IllegalArgumentException("Direction must be 1 or -1");
    }

    // If start and stop are the same, return a circulator positioned at stop
    if (start.equals(stop)) {
        return new OuterFaceCirculator(stop, dir);
    }

    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    Node first = circ.getNode();

    while (true) {
        Node current = circ.getNode();
        if (current == null) {
            throw new IllegalStateException("Circulator returned null node");
        }
        if (predicate.test(current)) {
            return circ;
        }
        if (current.equals(stop)) {
            return circ;
        }
        circ.next(); // advance to the next node in the specified direction
        // If we loop back to the starting node without finding the stop node or a matching node,
        // break to avoid an infinite loop and return a circulator positioned at the stop node.
        if (circ.getNode().equals(first)) {
            return new OuterFaceCirculator(stop, dir);
        }
    }
}

