public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    if (byteArrayValue != null) {
        if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
            throw new IllegalArgumentException("byteOffset out of bounds");
        }
        if (byteOffset + byteLength > byteArrayValue.length) {
            throw new IllegalArgumentException("byteOffset + byteLength exceeds array length");
        }
    }
    int newSize = size + byteLength;
    if (newSize < 0) { // overflow
        throw new IllegalArgumentException("Resulting size exceeds maximum array size");
    }
    if (buffer == null) {
        buffer = new byte[Math.max(16, newSize)];
    } else if (buffer.length < newSize) {
        int newCapacity = Math.max(buffer.length * 2, newSize);
        byte[] newBuffer = new byte[newCapacity];
        System.arraycopy(buffer, 0, newBuffer, 0, size);
        buffer = newBuffer;
    }
    if (byteArrayValue == null) {
        java.util.Arrays.fill(buffer, size, newSize, (byte) 0);
    } else {
        System.arraycopy(byteArrayValue, byteOffset, buffer, size, byteLength);
    }
    size = newSize;
    return this;
}

