public static String deleteAny(String inString, String charsToDelete) {
    if (inString == null) {
        throw new IllegalArgumentException("inString must not be null");
    }
    if (charsToDelete == null) {
        throw new IllegalArgumentException("charsToDelete must not be null");
    }

    // If nothing to delete, return the original string
    if (charsToDelete.isEmpty()) {
        return inString;
    }

    // Build a lookup table for characters to delete
    boolean[] deleteTable = new boolean[Character.MAX_VALUE + 1];
    for (int i = 0; i < charsToDelete.length(); i++) {
        deleteTable[charsToDelete.charAt(i)] = true;
    }

    StringBuilder result = new StringBuilder(inString.length());
    for (int i = 0; i < inString.length(); i++) {
        char c = inString.charAt(i);
        if (!deleteTable[c]) {
            result.append(c);
        }
    }

    return result.toString();
}

