private void check(String modelName) throws IllegalStateException {
    if (modelName == null) {
        throw new IllegalArgumentException("modelName cannot be null");
    }
    java.util.List<Integer> indices = shardingKeyIndicesMap.get(modelName);
    if (indices == null || indices.isEmpty()) {
        return;
    }
    java.util.Collections.sort(indices);
    for (int i = 1; i < indices.size(); i++) {
        Integer prev = indices.get(i - 1);
        Integer curr = indices.get(i);
        if (prev == null || curr == null) {
            throw new IllegalStateException("Sharding key indices for model " + modelName + " contain null values");
        }
        if (curr - prev != 1) {
            throw new IllegalStateException("Sharding key indices for model " + modelName + " are not continuous");
        }
    }
}

