        try {
            bytesRead = in.read(buffer, 0, buffer.length);
        } catch (IOException e) {
            // Propagate any I/O errors from the underlying stream
            throw e;
        }

        if (bytesRead <= 0) {
            // No more data available
            throw new IOException("End of stream");
        }

        // Reset position and limit after refilling
        pos = 0;
        limit = bytesRead;
    }

    // Return the next byte from the buffer
    return buffer[pos++];
}

