    int index = (hash & 0x7FFFFFFF) % table.length;

    // Search the bucket
    for (Entry<K, V> e = table[index]; e != null; e = e.next) {
        if (e.key == key || key.equals(e.key)) {
            return true;
        }
    }
    return false;
}

