public int addConstantNameAndType(final String name, final String descriptor) {
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("name and descriptor must not be null");
    }
    if (this.constantPool == null) {
        throw new IllegalStateException("constant pool is not initialized");
    }
    // Search for an existing CONSTANT_NameAndType_info with the same name and descriptor
    for (int i = 0; i < this.constantPool.size(); i++) {
        ConstantPoolInfo info = this.constantPool.get(i);
        if (info instanceof ConstantNameAndTypeInfo) {
            ConstantNameAndTypeInfo nt = (ConstantNameAndTypeInfo) info;
            if (name.equals(nt.getName()) && descriptor.equals(nt.getDescriptor())) {
                return i; // Return the index of the existing entry
            }
        }
    }
    // No existing entry found; create and add a new one
    ConstantNameAndTypeInfo newEntry = new ConstantNameAndTypeInfo(name, descriptor);
    this.constantPool.add(newEntry);
    return this.constantPool.size() - 1; // Return the index of the newly added entry
}

private String unescapeId(String input){
    if (input == null) {
        throw new NullPointerException("input cannot be null");
    }
    StringBuilder sb = new StringBuilder(input.length());
    int len = input.length();
    for (int i = 0; i < len; i++) {
        char c = input.charAt(i);
        if (c != '\\') {
            sb.append(c);
            continue;
        }
        // Escape sequence
        if (i + 1 >= len) {
            throw new IllegalArgumentException("Trailing backslash at end of input");
        }
        char next = input.charAt(i + 1);
        switch (next) {
            case 'n':
                sb.append('\n');
                i++;
                break;
            case 't':
                sb.append('\t');
                i++;
                break;
            case 'r':
                sb.append('\r');
                i++;
                break;
            case 'b':
                sb.append('\b');
                i++;
                break;
            case 'f':
                sb.append('\f');
                i++;
                break;
            case 'v':
                sb.append('\u000B'); // vertical tab
                i++;
                break;
            case '0':
                sb.append('\0');
                i++;
                break;
            case '\\':
                sb.append('\\');
                i++;
                break;
            case 'x':
                if (i + 3 >= len) {
                    throw new IllegalArgumentException("Invalid \\x escape: insufficient hex digits");
                }
                String hex2 = input.substring(i + 2, i + 4);
                try {
                    int val2 = Integer.parseInt(hex2, 16);
                    sb.append((char) val2);
                } catch (NumberFormatException e) {
                    throw new IllegalArgumentException("Invalid \\x escape: non-hex digits");
                }
                i += 3;
                break;
            case 'u':
                if (i + 5 >= len) {
                    throw new IllegalArgumentException("Invalid \\u escape: insufficient hex digits");
                }
                String hex4 = input.substring(i + 2, i + 6);
                try {
                    int val4 = Integer.parseInt(hex4, 16);
                    sb.append((char) val4);
                } catch (NumberFormatException e) {
                    throw new IllegalArgumentException("Invalid \\u escape: non-hex digits");
                }
                i += 5;
                break;
            case 'U':
                if (i + 9 >= len) {
                    throw new IllegalArgumentException("Invalid \\U escape: insufficient hex digits");
                }
                String hex8 = input.substring(i + 2, i + 10);
                try {
                    int val8 = Integer.parseInt(hex8, 16);
                    char[] chars = Character.toChars(val8);
                    sb.append(chars);
                } catch (NumberFormatException e) {
                    throw new IllegalArgumentException("Invalid \\U escape: non-hex digits");
                } catch (IllegalArgumentException e) {
                    throw new IllegalArgumentException("Invalid \\U escape: code point out of range");
                }
                i += 9;
                break;
            default:
                // Any other character is taken literally
                sb.append(next);
                i++;
                break;
        }
    }
    return sb.toString();
}

public static String[] concatenateStringArrays(String[] array1, String[] array2) {
    // If both arrays are null, return null as specified
    if (array1 == null && array2 == null) {
        return null;
    }

    // If one of the arrays is null, return a copy of the other array
    if (array1 == null) {
        return array2.clone();
    }
    if (array2 == null) {
        return array1.clone();
    }

    // Both arrays are non-null; concatenate them
    int len1 = array1.length;
    int len2 = array2.length;
    String[] result = new String[len1 + len2];

    // Copy elements from the first array
    System.arraycopy(array1, 0, result, 0, len1);

    // Copy elements from the second array
    System.arraycopy(array2, 0, result, len1, len2);

    return result;
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null) {
        throw new IllegalArgumentException("bucketsByLabel cannot be null");
    }
    if (labels == null) {
        throw new IllegalArgumentException("labels cannot be null");
    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("minLabel out of bounds");
    }
    if (minLabel == 0) {
        // Nothing to move if the minimum label is already 0
        return;
    }

    Set<Integer> source = bucketsByLabel.get(minLabel);
    if (source == null || source.isEmpty()) {
        // Nothing to move
        return;
    }

    Set<Integer> target = bucketsByLabel.get(0);
    if (target == null) {
        target = new java.util.HashSet<Integer>();
        bucketsByLabel.set(0, target);
    }

    for (Integer v : source) {
        if (v == null) {
            continue;
        }
        if (v < 0 || v >= labels.size()) {
            throw new IllegalArgumentException("Vertex index out of bounds: " + v);
        }
        labels.set(v, 0);
        target.add(v);
    }

    source.clear();
}

