public boolean isCompatible(DataTable dataset){
    if (dataset == null) {
        return false;
    }
    try {
        // Retrieve bucket from the provided dataset via reflection
        Object datasetBucketObj = dataset.getClass()
                                         .getMethod("getBucket")
                                         .invoke(dataset);
        if (datasetBucketObj == null) {
            return false;
        }
        String datasetBucket = datasetBucketObj.toString();

        // Retrieve bucket from the current instance via reflection
        Object thisBucketObj = this.getClass()
                                   .getMethod("getBucket")
                                   .invoke(this);
        if (thisBucketObj == null) {
            return false;
        }
        String thisBucket = thisBucketObj.toString();

        return thisBucket.equals(datasetBucket);
    } catch (Exception e) {
        // Any reflection-related exception or missing method results in incompatibility
        return false;
    }
}

