void removeSelf() {
    try {
        // If this bucket has a previous bucket, link it to this bucket's next
        if (prev != null) {
            prev.next = next;
        } else {
            // This bucket is the head of the list; the caller should update the head reference
            if (next != null) {
                next.prev = null;
            }
        }
        // If this bucket has a next bucket, link it back to this bucket's previous
        if (next != null) {
            next.prev = prev;
        }
        // Detach this bucket from the list
        prev = null;
        next = null;
    } catch (Exception e) {
        throw new IllegalStateException("Failed to remove bucket from data structure", e);
    }
}

