private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        throw new IllegalArgumentException("node cannot be null");
    }

    // Update links for head and tail
    if (node == head) {
        head = node.next;
        if (head != null) {
            head.prev = null;
        } else {
            tail = null; // list becomes empty
        }
    } else {
        node.prev.next = node.next;
    }

    if (node == tail) {
        tail = node.prev;
        if (tail != null) {
            tail.next = null;
        } else {
            head = null; // list becomes empty
        }
    } else {
        node.next.prev = node.prev;
    }

    // Clean up the removed node
    node.prev = null;
    node.next = null;
    size--;

    return true;
}

public java.util.List<SequenceRange> buildSequenceRanges() {
    java.util.List<SequenceRange> ranges = new java.util.ArrayList<>();
    try {
        java.util.List<Profile> profiles = getCurrentProfiles();
        if (profiles == null || profiles.isEmpty()) {
            throw new IllegalStateException("No current profiles available");
        }
        for (Profile profile : profiles) {
            java.util.List<Segment> segments = profile.getSegments();
            if (segments == null) continue;
            for (Segment segment : segments) {
                java.util.List<Snapshot> snapshots = segment.getSnapshots();
                if (snapshots == null) continue;
                for (Snapshot snapshot : snapshots) {
                    long start = snapshot.getStart();
                    long end = snapshot.getEnd();
                    if (start <= end) {
                        ranges.add(new SequenceRange(start, end));
                    }
                }
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to build sequence ranges", e);
    }
    return ranges;
}

