public static String stripFilenameExtension(String path){
    if (path == null || path.isEmpty()) {
        return null;
    }
    // Find last slash or backslash
    int lastSlash = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    // If path ends with a slash, no filename
    if (lastSlash == path.length() - 1) {
        return null;
    }
    // Find last dot after the last slash
    int lastDot = path.lastIndexOf('.');
    if (lastDot <= lastSlash) {
        // No dot after the last slash or dot is part of directory name
        return null;
    }
    // If dot is the first character of the filename (e.g., ".bashrc") or the last character (e.g., "file.")
    if (lastDot == lastSlash + 1 || lastDot == path.length() - 1) {
        return null;
    }
    return path.substring(0, lastDot);
}

