private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null) {
        throw new IllegalArgumentException("bounds cannot be null");
    }
    int n = bounds.size();
    List<Integer> suffixList = new ArrayList<>(n);
    long totalSum = 0L;
    for (Integer val : bounds) {
        if (val == null) {
            throw new IllegalArgumentException("bounds contains null element");
        }
        totalSum += val;
    }
    long suffixSum = 0L;
    int[] temp = new int[n];
    for (int i = n - 1; i >= 0; i--) {
        suffixSum += bounds.get(i);
        temp[i] = (int) suffixSum; // cast to int as per signature
    }
    for (int val : temp) {
        suffixList.add(val);
    }
    return new Pair<>(suffixList, totalSum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new NullPointerException("Array cannot be null");
    }
    int n = arr.length;
    if (from < 0 || to < 0 || from >= n || to >= n) {
        throw new IndexOutOfBoundsException("Indices out of bounds");
    }
    if (from > to) {
        throw new IllegalArgumentException("From index cannot be greater than to index");
    }
    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        throw new IllegalArgumentException("Source list cannot be null");
    }
    if (list == this) {
        return; // nothing to do
    }
    if (list.isEmpty()) {
        return; // nothing to move
    }

    // Detach the nodes from the source list
    ListNode<E> first = list.head.next;   // first real node
    ListNode<E> last = list.tail.prev;    // last real node

    // Connect the detached segment to this list
    ListNode<E> thisLast = this.tail.prev; // current last node of this list
    thisLast.next = first;
    first.prev = thisLast;

    last.next = this.tail;
    this.tail.prev = last;

    // Update sizes
    this.size += list.size;
    list.size = 0;

    // Reset the source list to empty
    list.head.next = list.tail;
    list.tail.prev = list.head;
}

