public void putAllWriteable(BeanMap map){
    if (map == null) {
        throw new IllegalArgumentException("map cannot be null");
    }
    for (Object keyObj : map.keySet()) {
        if (!(keyObj instanceof String)) {
            continue; // skip non-string keys
        }
        String key = (String) keyObj;
        try {
            // Only consider properties that are readable and writable in the source map
            if (!map.isReadable(key) || !map.isWritable(key)) {
                continue;
            }
            // Only set properties that are writable in this map
            if (!this.isWritable(key)) {
                continue;
            }
            Object value = map.get(key);
            this.put(key, value);
        } catch (Exception e) {
            // Ignore properties that cause exceptions during access or assignment
            // Optionally log the exception if a logging framework is available
        }
    }
}

