public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null) {
        throw new NullPointerException("table must not be null");
    }
    if (pane == null) {
        throw new NullPointerException("pane must not be null");
    }
    if (row < 0 || row >= table.getRowCount()) {
        throw new IllegalArgumentException("row index out of bounds: " + row);
    }
    // Verify that the table is the view component of the scroll pane
    if (pane.getViewport().getView() != table) {
        throw new IllegalArgumentException("The specified table is not the view of the provided JScrollPane");
    }

    // Select the row
    table.setRowSelectionInterval(row, row);

    // Scroll to make the row visible
    Rectangle cellRect = table.getCellRect(row, 0, true);
    if (cellRect != null) {
        table.scrollRectToVisible(cellRect);
    }

    // Delay repaint to allow the table to paint the newly selected row
    SwingUtilities.invokeLater(() -> table.repaint());
}

public ByteVector putInt(final int intValue){
    try {
        int required = size + 4;
        if (required > buffer.length) {
            int newCapacity = Math.max(buffer.length * 2, required);
            byte[] newBuffer = new byte[newCapacity];
            System.arraycopy(buffer, 0, newBuffer, 0, size);
            buffer = newBuffer;
        }
        buffer[size]     = (byte)(intValue >> 24);
        buffer[size + 1] = (byte)(intValue >> 16);
        buffer[size + 2] = (byte)(intValue >> 8);
        buffer[size + 3] = (byte)(intValue);
        size += 4;
        return this;
    } catch (Exception e) {
        throw new RuntimeException("Failed to put int into ByteVector", e);
    }
}

public static boolean arrayequals(byte[] a, byte[] b, int count) {
    if (a == null || b == null) {
        throw new NullPointerException("Input arrays must not be null");
    }
    if (count < 0) {
        throw new IllegalArgumentException("Count must be non‑negative");
    }
    if (count > a.length || count > b.length) {
        throw new IllegalArgumentException("Count exceeds array length");
    }
    for (int i = 0; i < count; i++) {
        if (a[i] != b[i]) {
            return false;
        }
    }
    return true;
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null) {
        throw new IllegalArgumentException("Buffer cannot be null");
    }
    if (name == null) {
        throw new IllegalArgumentException("Name cannot be null");
    }
    if (nameStart < 0 || nameStart > name.length()) {
        throw new IllegalArgumentException("nameStart out of bounds");
    }
    String sub = name.substring(nameStart).trim();
    if (sub.isEmpty()) {
        return;
    }
    String[] parts = sub.split("\\s+");
    for (int i = 0; i < parts.length; i++) {
        String part = parts[i];
        if (i < parts.length - 1) {
            buf.append(part.charAt(0)).append('.');
        } else {
            buf.append(part);
        }
        if (i < parts.length - 1) {
            buf.append(' ');
        }
    }
}

public static Type resolveBound(TypeVariable<?> typeVariable) {
    if (typeVariable == null) {
        throw new IllegalArgumentException("typeVariable must not be null");
    }
    Type[] bounds = typeVariable.getBounds();
    if (bounds == null || bounds.length == 0) {
        return Unknown.class;
    }
    Type first = bounds[0];
    if (first instanceof Class) {
        return first;
    }
    if (first instanceof java.lang.reflect.ParameterizedType) {
        return first;
    }
    if (first instanceof TypeVariable) {
        if (first == typeVariable) {
            return Unknown.class;
        }
        try {
            return resolveBound((TypeVariable<?>) first);
        } catch (Exception e) {
            return Unknown.class;
        }
    }
    return Unknown.class;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null) {
        throw new IllegalArgumentException("Graph must not be null");
    }
    if (vertices == null) {
        throw new IllegalArgumentException("Vertices set must not be null");
    }
    // A null vertex in the set would cause a NullPointerException when checking edges
    for (V v : vertices) {
        if (v == null) {
            throw new IllegalArgumentException("Vertices set must not contain null elements");
        }
    }
    // Trivially true for 0 or 1 vertex
    if (vertices.size() <= 1) {
        return true;
    }
    // Convert to array for indexed access
    Object[] arr = vertices.toArray();
    int n = arr.length;
    @SuppressWarnings("unchecked")
    V[] verts = (V[]) arr;
    for (int i = 0; i < n; i++) {
        V vi = verts[i];
        for (int j = i + 1; j < n; j++) {
            V vj = verts[j];
            // For undirected graphs, containsEdge should be symmetric
            if (graph.getEdge(vi, vj) == null) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    if (keys == null) {
        throw new IllegalArgumentException("Input list cannot be null");
    }
    int n = keys.size();
    List<Integer> result = new ArrayList<>(n);
    if (n == 0) {
        return result;
    }
    // Convert to Integer list and validate
    List<Integer> intKeys = new ArrayList<>(n);
    for (K k : keys) {
        if (k == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
        if (!(k instanceof Integer)) {
            throw new IllegalArgumentException("All keys must be instances of Integer");
        }
        intKeys.add((Integer) k);
    }
    // Create sorted copy
    List<Integer> sorted = new ArrayList<>(intKeys);
    Collections.sort(sorted);
    // For each key, find its lower bound
    for (Integer key : intKeys) {
        int idx = Collections.binarySearch(sorted, key);
        if (idx < 0) {
            // Should not happen because key is in sorted list
            result.add(null);
        } else if (idx == 0) {
            result.add(null);
        } else {
            result.add(sorted.get(idx - 1));
        }
    }
    return result;
}

