public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath must not be null");
    }

    boolean isAbsolute = path.startsWith("/");
    // Split the base path into components, ignoring empty parts
    String[] baseParts = path.split("/");
    java.util.ArrayDeque<String> stack = new java.util.ArrayDeque<>();
    for (String part : baseParts) {
        if (!part.isEmpty()) {
            stack.addLast(part);
        }
    }

    // Split the relative path into components, ignoring empty parts
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        } else if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            }
        } else {
            stack.addLast(part);
        }
    }

    // Build the resulting path
    StringBuilder result = new StringBuilder();
    if (isAbsolute) {
        result.append("/");
    }
    java.util.Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        result.append(it.next());
        if (it.hasNext()) {
            result.append("/");
        }
    }

    // If the result is empty, return "." for relative or "/" for absolute
    if (result.length() == 0) {
        return isAbsolute ? "/" : ".";
    }
    return result.toString();
}

