static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return null;
    }
    int count = 0;
    for (Object obj : array) {
        if (obj != null) {
            count++;
        }
    }
    if (count == 0) {
        return new String[0];
    }
    String[] result = new String[count];
    int idx = 0;
    for (Object obj : array) {
        if (obj != null) {
            try {
                result[idx++] = (String) obj;
            } catch (ClassCastException e) {
                throw new IllegalArgumentException("Array contains non-String element", e);
            }
        }
    }
    return result;
}

public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }
    int lastDot = filename.lastIndexOf('.');
    if (lastDot == -1) {
        return -1;
    }
    int lastSeparator = indexOfLastSeparator(filename);
    return (lastDot > lastSeparator) ? lastDot : -1;
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    if (timestamp < 0) {
        throw new IllegalArgumentException("timestamp must be non-negative");
    }
    if (expiredThreshold < 0) {
        throw new IllegalArgumentException("expiredThreshold must be non-negative");
    }
    long currentTime = System.currentTimeMillis();
    return currentTime - timestamp > expiredThreshold;
}

Edge edgeToNext() {
    try {
        // Retrieve the previously returned node and the node that will be returned next
        Node prevNode = this.previousNode;
        Node nextNode = this.nextNode;

        // Validate that both nodes are available
        if (prevNode == null || nextNode == null) {
            throw new IllegalStateException("Previous or next node is not set.");
        }

        // Resolve virtual nodes to their real counterparts, if necessary
        Node realPrev = prevNode.isVirtual() ? prevNode.getRealNode() : prevNode;
        Node realNext = nextNode.isVirtual() ? nextNode.getRealNode() : nextNode;

        // Create and return the edge connecting the two real nodes
        return new Edge(realPrev, realNext);
    } catch (Exception e) {
        // Wrap any unexpected exception in a runtime exception with a clear message
        throw new RuntimeException("Unable to create edge to next node", e);
    }
}

public static boolean substringMatch(CharSequence str,int index,CharSequence substring){
    if (str == null || substring == null) {
        throw new NullPointerException("str and substring must not be null");
    }
    int strLen = str.length();
    int subLen = substring.length();
    if (index < 0 || index > strLen - subLen) {
        return false;
    }
    for (int i = 0; i < subLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

protected void append(LoggingEvent event) {
    if (event == null) {
        return;
    }
    String message = event.getFormattedMessage();
    if (message == null) {
        message = "";
    }
    if (clients == null || clients.isEmpty()) {
        return;
    }
    for (Client client : clients) {
        if (client == null) {
            continue;
        }
        try {
            client.send(message);
        } catch (Exception e) {
            // Log the error; adjust as needed for your logging framework
            e.printStackTrace();
        }
    }
}

private void checkIfPackedField() throws IOException {
    // A packed repeated field is encoded as a length‑delimited field (wire type 2).
    if (currentWireType == 2) { // WIRETYPE_LENGTH_DELIMITED
        // Read the length of the packed data.
        int length = readVarint32();
        if (length < 0) {
            throw new IOException("Negative packed field length: " + length);
        }
        // Record the size and the end position of the packed field.
        packedFieldSize = length;
        packedFieldEnd = input.position() + length;
        // Mark that we are currently reading a packed field.
        isPackedField = true;
    } else {
        // Not a packed field.
        isPackedField = false;
    }
}

public int readTag() throws IOException {
    int tag = 0;
    int shift = 0;
    while (shift < 32) {
        int b = input.read();
        if (b == -1) {
            // EOF reached before any bytes were read
            return 0;
        }
        tag |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            break;
        }
        shift += 7;
    }
    if (shift >= 32) {
        throw new IOException("Malformed varint");
    }
    // Tag 0 is not a valid field tag; treat it as EOF
    return tag == 0 ? 0 : tag;
}

private String buildContentRange() {
    try {
        if (start < 0 || end < 0) {
            throw new IllegalArgumentException("Start and end byte positions must be non-negative");
        }
        if (start > end) {
            throw new IllegalArgumentException("Start byte must be less than or equal to end byte");
        }
        StringBuilder sb = new StringBuilder();
        sb.append("bytes ");
        sb.append(start).append("-").append(end).append("/");
        sb.append(total >= 0 ? total : "*");
        return sb.toString();
    } catch (Exception e) {
        throw new RuntimeException("Failed to build Content-Range header", e);
    }
}

public static java.util.List<ThreadSnapshot> parseFromFileWithTimeRange(java.io.File file, java.util.List<ProfileAnalyzeTimeRange> timeRanges) throws java.io.IOException {
    if (file == null) {
        throw new IllegalArgumentException("file must not be null");
    }
    if (timeRanges == null) {
        throw new IllegalArgumentException("timeRanges must not be null");
    }
    if (!file.exists()) {
        throw new java.io.FileNotFoundException("File does not exist: " + file.getAbsolutePath());
    }
    if (!file.isFile()) {
        throw new java.io.IOException("Not a regular file: " + file.getAbsolutePath());
    }
    if (timeRanges.isEmpty()) {
        return java.util.Collections.emptyList();
    }

    java.util.List<ThreadSnapshot> result = new java.util.ArrayList<>();
    try (java.io.ObjectInputStream ois = new java.io.ObjectInputStream(new java.io.BufferedInputStream(new java.io.FileInputStream(file)))) {
        while (true) {
            try {
                Object obj = ois.readObject();
                if (obj instanceof ThreadSnapshot) {
                    ThreadSnapshot ts = (ThreadSnapshot) obj;
                    long tsTime = ts.getTimestamp(); // assume ThreadSnapshot has getTimestamp()
                    for (ProfileAnalyzeTimeRange range : timeRanges) {
                        long start = range.getStartTime(); // assume getter
                        long end = range.getEndTime();     // assume getter
                        if (tsTime >= start && tsTime <= end) {
                            result.add(ts);
                            break;
                        }
                    }
                }
            } catch (java.io.EOFException eof) {
                break;
            } catch (ClassNotFoundException cnf) {
                throw new java.io.IOException("Failed to deserialize ThreadSnapshot", cnf);
            }
        }
    }
    return result;
}
